// Define a fluid handler for a tank
public class MyFluidTank implements IFluidTank {
    private FluidStack stack = FluidStack.EMPTY;
    private int capacity = 1000;

    @Override
    public FluidStack getFluid() { return stack; }

    @Override
    public int getCapacity() { return capacity; }

    @Override
    public boolean isEmpty() { return stack.isEmpty(); }

    @Override
    public int fill(FluidStack resource, FluidAction action) {
        if (resource.isEmpty() || !resource.getFluid().isSame(getFluid().getFluid())) {
            return 0;
        }
        int toFill = Math.min(resource.getAmount(), capacity - stack.getAmount());
        if (action.execute()) {
            stack.setAmount(stack.getAmount() + toFill);
        }
        return toFill;
    }

    @Override
    public FluidStack drain(FluidStack resource, FluidAction action) {
        if (resource.isEmpty() || !resource.getFluid().isSame(getFluid().getFluid())) {
            return FluidStack.EMPTY;
        }
        return drain(resource.getAmount(), action);
    }
}

